entry:
  c0 = const 0
  jmp header
header:
  i = phi(entry: c0, L1: i1, L2: i2)
  k = phi(entry: c0, L1: k, L2: k)
  cond = lt i, %n
  br cond, check, exit
check:
  two = const 2
  r = rem i, two
  zero = const 0
  isz = eq r, zero
  br isz, L1, L2
L1:
  one = const 1
