import unittest

import ssa_phi_pruning as ssa


class RoundTripTests(unittest.TestCase):
    def test_parse_emit_parse_is_stable(self):
        for name, text in ssa.SAMPLES.items():
            with self.subTest(sample=name):
                a = ssa.parse(text)
                b = ssa.parse(ssa.emit(a))
                self.assertTrue(ssa.same_program(a, b),
                                f"round-trip changed {name}")

    def test_emit_is_parseable_after_optimize(self):
        for name, text in ssa.SAMPLES.items():
            with self.subTest(sample=name):
                fn = ssa.parse(text)
                ssa.optimize(fn)
                again = ssa.parse(ssa.emit(fn))
                self.assertTrue(ssa.same_program(fn, again))
                again.recompute_edges()
                self.assertEqual(set(fn.blocks), set(again.blocks))


class PruningTests(unittest.TestCase):
    def test_all_same_phi_is_deleted(self):
        fn = ssa.parse(ssa.SAMPLES["diamond_trivial"])
        stats = ssa.optimize(fn)
        self.assertIn("x", stats.phis_removed)
        self.assertEqual(stats.phis_after, 0)

    def test_transitive_chain_needs_worklist(self):
        fn = ssa.parse(ssa.SAMPLES["chain"])
        stats = ssa.optimize(fn)
        self.assertEqual(set(stats.phis_removed), {"x", "y"})
        self.assertEqual(stats.phis_after, 0)

    def test_self_reference_phi_is_deleted_on_proper_loop(self):
        fn = ssa.parse(ssa.SAMPLES["self_loop"])
        stats = ssa.optimize(fn)
        self.assertIn("v1", stats.phis_removed)
        self.assertEqual(stats.phis_after, 0)

    def test_multiple_backedges_keep_conflicting_phi(self):
        fn = ssa.parse(ssa.SAMPLES["multi_backedge"])
        stats = ssa.optimize(fn)
        self.assertIn("k", stats.phis_removed)
        self.assertNotIn("i", stats.phis_removed)
        self.assertEqual(stats.phis_after, 1)

    def test_conservative_on_irreducible(self):
        fn = ssa.parse(ssa.SAMPLES["irreducible"])
        stats = ssa.optimize(fn)
        self.assertFalse(stats.reducible)
        self.assertIn("x", stats.conservative_phis)
        self.assertIn("z", stats.conservative_phis)
        self.assertEqual(stats.phis_after, stats.phis_before)
        self.assertTrue(stats.copies_inserted)

    def test_nested_loops_nothing_is_wrongly_pruned(self):
        fn = ssa.parse(ssa.SAMPLES["nested_loops"])
        stats = ssa.optimize(fn)
        self.assertEqual(stats.phis_removed, [])


