            rows = ssa.random_inputs(ssa.parse(ssa.SAMPLES["irreducible"]),
                                     n=100, lo=-2, hi=3, seed=seed)
            ok, cex = ssa.check_equivalence(ssa.SAMPLES["irreducible"], rows)
            self.assertTrue(ok, cex)


